rrent_setting('nexus.tenant', true), n.m_chash, n.m_topic_id, 'centroid', p_collection FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO NOTHING RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, NULL::double precision FROM nearest n; END IF; END; $fn$;
CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_384( p_query vector(384), p_topic_label text, p_collection text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 <=> p_query)::float8 FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = encode(c.chash, 'hex') JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_384 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash) OR EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL)) ORDER BY c.embedding_384 <=> p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_768( p_query vector(768), p_topic_label text, p_collection text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 <=> p_query)::float8 FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = encode(c.chash, 'hex') JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_768 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash) OR EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL)) ORDER BY c.embedding_768 <=> p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_1024( p_query vector(1024), p_topic_label text, p_collection text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 <=> p_query)::float8 FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = encode(c.chash, 'hex') JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_1024 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash) OR EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL)) ORDER BY c.embedding_1024 <=> p_query LIMIT p_n $$;

DO $$
BEGIN
    BEGIN
        DROP VIEW IF EXISTS nexus.diag_chash_conformance;
    EXCEPTION WHEN insufficient_privilege THEN
        RAISE EXCEPTION 'RDR-194 P3c (nexus-tk070.p3c, nexus-7ec4i): nexus.diag_chash_conformance exists but this migration role does not own it and cannot drop it. Changeset taxonomy-011-1''s rollback (doc_id TYPE TEXT) cannot proceed while ANY view depends on doc_id, regardless of ownership. Remedy: the view''s owning role must run DROP VIEW IF EXISTS nexus.diag_chash_conformance, then retry this rollback.';
    END;
END
$$;
